package com.nekoflow.catalog;

import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;

@RestController @RequestMapping("/api/v1")
public class CatalogV1Controller {
  private final JdbcClient jdbc;
  public CatalogV1Controller(JdbcClient jdbc){this.jdbc=jdbc;}

  @GetMapping("/works")
  public Map<String,Object> works(@RequestParam(defaultValue="") String q,@RequestParam(required=false) String media,
    @RequestParam(required=false) String genre,@RequestParam(required=false) String origin,@RequestParam(required=false) String status,
    @RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="24") int size){
    if(page<0||size<1||size>100) throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Paginação inválida");
    String like="%"+q.trim().toLowerCase()+"%";
    String where="w.visibility='PUBLISHED' AND (:media IS NULL OR w.media_family=:media) AND (:origin IS NULL OR w.origin_country=:origin) AND (:status IS NULL OR w.story_status=:status) AND (:genre IS NULL OR EXISTS(SELECT 1 FROM work_genre wg JOIN genre g ON g.id=wg.genre_id WHERE wg.work_id=w.id AND g.slug=:genre)) AND (:q='' OR lower(w.title) LIKE :like OR EXISTS(SELECT 1 FROM work_title wt WHERE wt.work_id=w.id AND wt.title_norm LIKE :like))";
    var query=jdbc.sql("SELECT w.* FROM work w WHERE "+where+" ORDER BY w.popularity DESC NULLS LAST,w.id LIMIT :size OFFSET :off")
      .param("media",blank(media)).param("origin",blank(origin)).param("status",blank(status)).param("genre",blank(genre)).param("q",q.trim()).param("like",like).param("size",size).param("off",page*size);
    var items=query.query((rs,n)->summary(rs.getLong("id"))).list();
    long total=jdbc.sql("SELECT count(*) FROM work w WHERE "+where).param("media",blank(media)).param("origin",blank(origin)).param("status",blank(status)).param("genre",blank(genre)).param("q",q.trim()).param("like",like).query(Long.class).single();
    return Map.of("items",items,"page",page,"size",size,"totalElements",total,"totalPages",(total+size-1)/size);
  }
  @GetMapping("/works/{id}") public Map<String,Object> detail(@PathVariable UUID id){long legacy=legacy(id);return detailMap(legacy);}
  @GetMapping("/works/resolve") public Map<String,Object> resolve(@RequestParam String section,@RequestParam String slug){
    return jdbc.sql("SELECT public_id FROM work WHERE visibility='PUBLISHED' AND slug=? AND media_family=?").params(slug,"animes".equals(section)?"ANIMATION":"READING").query(UUID.class).optional().map(this::detail).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Obra não encontrada"));}
  @GetMapping("/works/{id}/seasons") public List<Map<String,Object>> seasons(@PathVariable UUID id){return rows("SELECT id,title,display_number,sort_position,poster_url,release_date FROM season WHERE work_id=? AND visibility='PUBLISHED' ORDER BY sort_position",legacy(id));}
  @GetMapping("/seasons/{id}/episodes") public List<Map<String,Object>> episodes(@PathVariable UUID id){return rowsUuid("SELECT e.id,e.title,e.display_number,e.sort_position,e.synopsis,e.duration_seconds,e.original_air_date,e.availability,EXISTS(SELECT 1 FROM episode_source s WHERE s.episode_id=e.id AND s.enabled) AS has_source FROM episode e WHERE e.season_id=? ORDER BY e.sort_position",id);}
  @GetMapping("/episodes/{id}") public Map<String,Object> episode(@PathVariable UUID id){return jdbc.sql("SELECT e.id,e.title,e.display_number,e.sort_position,e.synopsis,e.duration_seconds,e.original_air_date,e.availability,w.public_id AS work_id,w.title AS work_title,w.slug FROM episode e JOIN season s ON s.id=e.season_id JOIN work w ON w.id=s.work_id WHERE e.id=? AND s.visibility='PUBLISHED' AND w.visibility='PUBLISHED'").param(id).query((rs,n)->row(rs)).optional().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Episódio não encontrado"));}
  @GetMapping("/works/{id}/volumes") public List<Map<String,Object>> volumes(@PathVariable UUID id){return rows("SELECT v.* FROM volume v JOIN work_edition e ON e.id=v.edition_id WHERE e.work_id=? ORDER BY v.sort_position",legacy(id));}
  @GetMapping("/works/{id}/editions") public List<Map<String,Object>> editions(@PathVariable UUID id){return rows("SELECT id,name,language,is_original FROM work_edition WHERE work_id=? ORDER BY is_original DESC,name",legacy(id));}
  @GetMapping("/works/{id}/chapters") public List<Map<String,Object>> chapters(@PathVariable UUID id){return rows("SELECT c.*,e.name AS edition_name,e.language,EXISTS(SELECT 1 FROM chapter_source s WHERE s.chapter_id=c.id AND s.enabled) AS has_source FROM chapter c JOIN work_edition e ON e.id=c.edition_id WHERE e.work_id=? ORDER BY e.is_original DESC,c.sort_position",legacy(id));}
  @GetMapping("/episodes/{id}/source") public Map<String,Object> episodeSource(@PathVariable UUID id){return source("SELECT source_type,source_url,provider,language,embed_allowed,provenance FROM episode_source WHERE episode_id=? AND enabled ORDER BY embed_allowed DESC,created_at LIMIT 1",id);}
  @GetMapping("/chapters/{id}/source") public Map<String,Object> chapterSource(@PathVariable UUID id){return source("SELECT source_type,source_url,provider,language,embed_allowed,provenance FROM chapter_source WHERE chapter_id=? AND enabled ORDER BY created_at LIMIT 1",id);}
  @GetMapping("/works/{id}/relations") public List<Map<String,Object>> relations(@PathVariable UUID id){return rows("SELECT r.id,r.relation_type,w.public_id,w.title,w.slug,w.media_family,'OUTBOUND' direction FROM work_relation r JOIN work w ON w.id=r.target_work_id WHERE r.source_work_id=? AND w.visibility='PUBLISHED'",legacy(id));}
  @GetMapping("/works/{id}/contributors") public List<Map<String,Object>> contributors(@PathVariable UUID id){return rows("SELECT p.id,p.name,c.role,c.position FROM work_contributor c JOIN person p ON p.id=c.person_id WHERE c.work_id=? ORDER BY c.position",legacy(id));}
  @GetMapping("/genres") public List<Map<String,Object>> genres(){return jdbc.sql("SELECT id,slug,name FROM genre ORDER BY name").query((rs,n)->Map.<String,Object>of("id",rs.getLong(1),"slug",rs.getString(2),"name",rs.getString(3))).list();}
  @GetMapping("/franchises/{id}") public Map<String,Object> franchise(@PathVariable UUID id){var f=jdbc.sql("SELECT slug,name FROM franchise WHERE id=?").param(id).query((rs,n)->new LinkedHashMap<String,Object>(Map.of("id",id,"slug",rs.getString(1),"name",rs.getString(2)))).optional().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));f.put("works",rowsUuid("SELECT w.public_id,w.title,w.slug,w.media_family FROM franchise_work fw JOIN work w ON w.id=fw.work_id WHERE fw.franchise_id=? AND w.visibility='PUBLISHED' ORDER BY fw.position",id));return f;}
  private Map<String,Object> summary(long id){return detailMap(id);}
  private Map<String,Object> detailMap(long id){var w=jdbc.sql("SELECT * FROM work WHERE id=? AND visibility='PUBLISHED'").param(id).query((rs,n)->{var m=new LinkedHashMap<String,Object>();m.put("id",rs.getObject("public_id"));m.put("legacyId",rs.getLong("id"));m.put("slug",rs.getString("slug"));m.put("mediaFamily",rs.getString("media_family"));m.put("format",rs.getString("work_format"));m.put("readingCategory",rs.getString("reading_category"));m.put("presentationFormat",rs.getString("presentation_format"));m.put("title",rs.getString("title"));m.put("synopsis",rs.getString("synopsis_full"));m.put("synopsisShort",rs.getString("synopsis_short"));m.put("storyStatus",rs.getString("story_status"));m.put("visibility",rs.getString("visibility"));m.put("coverUrl",rs.getString("cover"));m.put("bannerUrl",rs.getString("banner"));m.put("year",rs.getObject("year"));m.put("totalUnits",rs.getObject("total_units"));m.put("availableUnits",rs.getObject("available_units"));m.put("originCountry",rs.getString("origin_country"));m.put("hasPlayableContent",jdbc.sql("SELECT EXISTS(SELECT 1 FROM episode e JOIN season se ON se.id=e.season_id JOIN episode_source s ON s.episode_id=e.id AND s.enabled WHERE se.work_id=? UNION ALL SELECT 1 FROM chapter c JOIN work_edition ed ON ed.id=c.edition_id JOIN chapter_source s ON s.chapter_id=c.id AND s.enabled WHERE ed.work_id=? LIMIT 1)").params(id,id).query(Boolean.class).single());m.put("href",("ANIMATION".equals(rs.getString("media_family"))?"/animes/":"/leituras/")+rs.getString("slug"));return m;}).optional().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Obra não encontrada"));w.put("titles",rows("SELECT title,title_type,language FROM work_title WHERE work_id=? ORDER BY id",id));w.put("genres",rows("SELECT g.slug,g.name FROM work_genre wg JOIN genre g ON g.id=wg.genre_id WHERE wg.work_id=? ORDER BY wg.position",id));w.put("tags",rows("SELECT t.slug,t.name FROM work_tag wt JOIN tag t ON t.id=wt.tag_id WHERE wt.work_id=? ORDER BY t.name",id));w.put("seasonCount",jdbc.sql("SELECT count(*) FROM season WHERE work_id=? AND visibility='PUBLISHED'").param(id).query(Long.class).single());w.put("episodeCount",jdbc.sql("SELECT count(*) FROM episode e JOIN season s ON s.id=e.season_id WHERE s.work_id=? AND s.visibility='PUBLISHED'").param(id).query(Long.class).single());w.put("chapterCount",jdbc.sql("SELECT count(*) FROM chapter c JOIN work_edition e ON e.id=c.edition_id WHERE e.work_id=?").param(id).query(Long.class).single());return w;}
  private long legacy(UUID id){return jdbc.sql("SELECT id FROM work WHERE public_id=? AND visibility='PUBLISHED'").param(id).query(Long.class).optional().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Obra não encontrada"));}
  private Map<String,Object> source(String sql,UUID id){return jdbc.sql(sql).param(id).query((rs,n)->row(rs)).optional().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Fonte indisponível"));}
  private static Map<String,Object> row(java.sql.ResultSet rs) throws java.sql.SQLException {Map<String,Object> m=new LinkedHashMap<>();for(int i=1;i<=rs.getMetaData().getColumnCount();i++)m.put(rs.getMetaData().getColumnLabel(i),rs.getObject(i));return m;}
  private List<Map<String,Object>> rows(String sql,long id){return jdbc.sql(sql).param(id).query((rs,n)->row(rs)).list();}
  private List<Map<String,Object>> rowsUuid(String sql,UUID id){return jdbc.sql(sql).param(id).query((rs,n)->row(rs)).list();}
  private static String blank(String x){return x==null||x.isBlank()?null:x;}
}
